const itemConfig = $('Configuracao Unidades').first();
const dadosOriginais = itemConfig.json;
const configAgenda = dadosOriginais.config_agenda;

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
// Puxa a duração configurada (30 min)
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30; 
// Puxa a capacidade de cadeiras/salas
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 1;

// Eventos ocupados que vêm do Google Calendar
const eventosOcupados = $input.all().map(i => i.json);

const dataStr = dadosOriginais.data_agendada;
const horaStr = dadosOriginais.horario_agendado;
const dataAlvo = DateTime.fromFormat(`${dataStr} ${horaStr}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });

let validacao = { aprovado: false, motivo: '' };
const getMin = (cfg) => cfg.h * 60 + cfg.m;

if (!dataAlvo.isValid) {
    validacao.motivo = 'Data ou hora em formato inválido.';
} else {
    const diaSemana = dataAlvo.weekday;
    const regraDia = configAgenda.regras_horario[diaSemana];

    if (!regraDia) {
        validacao.motivo = `A unidade ${configAgenda.nome_unidade} não tem expediente neste dia da semana.`;
        validacao.aprovado = false;
    } else {
        const minSol = dataAlvo.hour * 60 + dataAlvo.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;

        // NOVA LÓGICA: Verifica se o horário encaixa na Manhã OU na Tarde
        let dentroDoExpediente = false;

        if (regraDia.manha && minSol >= getMin(regraDia.manha.ini) && minFimSol <= getMin(regraDia.manha.fim)) {
            dentroDoExpediente = true;
        }
        if (regraDia.tarde && minSol >= getMin(regraDia.tarde.ini) && minFimSol <= getMin(regraDia.tarde.fim)) {
            dentroDoExpediente = true;
        }

        if (!dentroDoExpediente) {
            validacao.motivo = `Horário fora do expediente da unidade ${configAgenda.nome_unidade}.`;
            validacao.aprovado = false;
        } else {
            const slotInicio = dataAlvo;
            const slotFim = dataAlvo.plus({ minutes: DURACAO_MINUTOS });

            let ocupadosSlot = 0;
            let ocupadosTurno = 0; // Novo contador do turno

            // Definir limites do turno atual para o contador
            let inicioTurno, fimTurno;
            if (regraDia.manha && minSol >= getMin(regraDia.manha.ini) && minFimSol <= getMin(regraDia.manha.fim)) {
                inicioTurno = dataAlvo.set({ hour: regraDia.manha.ini.h, minute: regraDia.manha.ini.m });
                fimTurno = dataAlvo.set({ hour: regraDia.manha.fim.h, minute: regraDia.manha.fim.m });
            } else if (regraDia.tarde && minSol >= getMin(regraDia.tarde.ini) && minFimSol <= getMin(regraDia.tarde.fim)) {
                inicioTurno = dataAlvo.set({ hour: regraDia.tarde.ini.h, minute: regraDia.tarde.ini.m });
                fimTurno = dataAlvo.set({ hour: regraDia.tarde.fim.h, minute: regraDia.tarde.fim.m });
            }

            for (const evento of eventosOcupados) {
                if (!evento || !evento.start || evento.status === 'cancelled') continue;

                let iniEvt = DateTime.fromISO(evento.start.dateTime || evento.start.date).setZone(TIMEZONE);
                let fimEvt = DateTime.fromISO(evento.end.dateTime || evento.end.date).setZone(TIMEZONE);

                // 1. Conta colisão exata (ex: 2 pessoas 14:00)
                if (slotInicio < fimEvt && slotFim > iniEvt) ocupadosSlot++;

                // 2. Conta total de pacientes alocados no turno todo
                if (inicioTurno && fimTurno && iniEvt >= inicioTurno && iniEvt < fimTurno) ocupadosTurno++;
            }

            const limiteTurno = configAgenda.capacidade_turno || 999; 

            if (ocupadosSlot >= CAPACIDADE_MAXIMA) {
                validacao.aprovado = false;
                validacao.motivo = `Infelizmente, este horário exato já foi preenchido na unidade ${configAgenda.nome_unidade}.`;
            } else if (ocupadosTurno >= limiteTurno) {
                validacao.aprovado = false;
                validacao.motivo = `A unidade ${configAgenda.nome_unidade} atingiu o limite de agendamentos para este período (manhã/tarde).`;
            } else {
                validacao.aprovado = true;
                validacao.motivo = 'Sucesso';
            }
        }
    }
}

return { json: { ...dadosOriginais, validacao } };

