const itemConfig = $('Configuracao Unidades').first().json;
const configAgenda = itemConfig.config_agenda || {};

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30;
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 1;
const MIN_GAP_MINUTES = 180; // Pausa mínima entre sugestões para dar variedade ao cliente

const feriados = configAgenda.feriados || [
    "2026-01-01", "2026-02-20", "2026-04-03", "2026-04-21", 
    "2026-05-01", "2026-06-11", "2026-09-07", "2026-10-12", 
    "2026-11-02", "2026-11-15", "2026-11-20", "2026-12-25"
]; 

const eventosOcupados = $input.all().map(i => i.json);
const agora = DateTime.now().setZone(TIMEZONE);

const horasTrava = configAgenda.trava_agendamento || 2;
const inicioSeguro = agora.plus({ hours: horasTrava });

const isFeriado = (data) => feriados.includes(data.toFormat('yyyy-MM-dd'));

function isSlotAvailable(slotStart) {
    if (isFeriado(slotStart)) return false; 
    let ocupados = 0;
    const slotEnd = slotStart.plus({ minutes: DURACAO_MINUTOS });

    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;
        let iniEvt, fimEvt;

        if (evento.start?.dateTime) {
            iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        } else if (evento.start?.date) {
            iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');
        } else { continue; }

        if (evento.end?.dateTime) {
            fimEvt = DateTime.fromISO(evento.end.dateTime).setZone(TIMEZONE);
        } else if (evento.end?.date) {
            fimEvt = DateTime.fromISO(evento.end.date).setZone(TIMEZONE).endOf('day');
        } else { continue; }

        if (slotStart < fimEvt && slotEnd > iniEvt) ocupados++;
    }
    return ocupados < CAPACIDADE_MAXIMA;
}

function isShiftAvailable(slotStart, regraDia) {
    if (!configAgenda.capacidade_turno) return true; // Se a unidade não tiver limite de turno, libera.

    const minSol = slotStart.hour * 60 + slotStart.minute;
    let turnoAlvo = null;

    if (isSlotInShift(minSol, minSol + DURACAO_MINUTOS, regraDia.manha)) turnoAlvo = regraDia.manha;
    else if (isSlotInShift(minSol, minSol + DURACAO_MINUTOS, regraDia.tarde)) turnoAlvo = regraDia.tarde;

    if (!turnoAlvo) return false;

    // Define os limites reais do turno (ex: 08:00 às 11:30)
    const inicioTurno = slotStart.set({ hour: turnoAlvo.ini.h, minute: turnoAlvo.ini.m });
    const fimTurno = slotStart.set({ hour: turnoAlvo.fim.h, minute: turnoAlvo.fim.m });

    let ocupadosNoTurno = 0;

    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;

        let iniEvt;
        if (evento.start?.dateTime) iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        else if (evento.start?.date) iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');

        // Se o evento existente cai dentro da janela deste turno, soma +1
        if (iniEvt && iniEvt >= inicioTurno && iniEvt < fimTurno) {
            ocupadosNoTurno++;
        }
    }

    return ocupadosNoTurno < configAgenda.capacidade_turno;
}

const getMin = (cfg) => cfg.h * 60 + cfg.m;

function isSlotInShift(minSol, minFimSol, shift) {
    if (!shift || (shift.ini.h === 0 && shift.fim.h === 0)) return false;
    return minSol >= getMin(shift.ini) && minFimSol <= getMin(shift.fim);
}

// Resgata os dados
const dataStr = itemConfig.data_agendada;
const horaStr = itemConfig.horario_agendado;
let diaSolicitado = dataStr ? DateTime.fromFormat(dataStr, 'dd/MM/yyyy', { zone: TIMEZONE }) : null;
let horarioSolicitado;

if (dataStr && horaStr) {
    horarioSolicitado = DateTime.fromFormat(`${dataStr} ${horaStr}`, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
} else if (itemConfig.data_iso) {
    horarioSolicitado = DateTime.fromISO(itemConfig.data_iso, { zone: TIMEZONE });
} else if (diaSolicitado && diaSolicitado.isValid) {
    horarioSolicitado = diaSolicitado;
} else {
    horarioSolicitado = agora;
}

const solicitouHorarioEspecifico = horarioSolicitado.isValid && horaStr && horaStr !== '00:00';
let solicitadoDisponivel = false;

// Verifica a disponibilidade do horário específico (considerando manhã e tarde)
if (solicitouHorarioEspecifico && horarioSolicitado >= inicioSeguro && !isFeriado(horarioSolicitado)) {
    const diaSem = horarioSolicitado.weekday;
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[diaSem] : null;

    if (regraDia) {
        const minSol = horarioSolicitado.hour * 60 + horarioSolicitado.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;

        const isManha = isSlotInShift(minSol, minFimSol, regraDia.manha);
        const isTarde = isSlotInShift(minSol, minFimSol, regraDia.tarde);

        if ((isManha || isTarde) && isSlotAvailable(horarioSolicitado) && isShiftAvailable(horarioSolicitado, regraDia)){
            solicitadoDisponivel = true;
        }
    }
}

// Lógica de Sugestões Inteligentes
let sugestoes = [];
let cursorDia = (diaSolicitado && diaSolicitado.isValid)
    ? diaSolicitado.startOf('day')
    : (solicitouHorarioEspecifico ? horarioSolicitado.startOf('day') : agora.startOf('day'));
if (cursorDia < agora.startOf('day')) cursorDia = agora.startOf('day');

let diasVerificados = 0;
const MAX_DIAS_BUSCA = 7;
const MAX_OPCOES = 3;
const periodo = itemConfig.periodo_preferencia || '';

while (sugestoes.length < MAX_OPCOES && diasVerificados < MAX_DIAS_BUSCA) {
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[cursorDia.weekday] : null;

    if (regraDia && !isFeriado(cursorDia)) {
        const turnos = [];

        // Filtra os turnos baseado na preferência do cliente (se houver)
        if (periodo === 'manha' && regraDia.manha) turnos.push(regraDia.manha);
        else if (periodo === 'tarde' && regraDia.tarde) turnos.push(regraDia.tarde);
        else {
            if (regraDia.manha) turnos.push(regraDia.manha);
            if (regraDia.tarde) turnos.push(regraDia.tarde);
        }

        // Procura horários dentro dos turnos válidos
        for (const turno of turnos) {
            // Pula turnos vazios/fechados (ex: Sábado à tarde)
            if (turno.ini.h === 0 && turno.fim.h === 0) continue;

            let loopTime = cursorDia.set({ hour: turno.ini.h, minute: turno.ini.m });
            const fimTurno = cursorDia.set({ hour: turno.fim.h, minute: turno.fim.m });

            while (loopTime.plus({minutes: DURACAO_MINUTOS}) <= fimTurno) {
                if (sugestoes.length >= MAX_OPCOES) break;

                if (loopTime >= inicioSeguro && isSlotAvailable(loopTime) && isShiftAvailable(loopTime, regraDia)) {
                    sugestoes.push(loopTime);
                    loopTime = loopTime.plus({ minutes: MIN_GAP_MINUTES });
                } else {
                    loopTime = loopTime.plus({ minutes: DURACAO_MINUTOS });
                }
            }
            if (sugestoes.length >= MAX_OPCOES) break;
        }
    }
    cursorDia = cursorDia.plus({ days: 1 });
    diasVerificados++;
}

// Montagem da resposta
let respostaFinal = '';
let sugestoesISO = [];

if (solicitadoDisponivel) {
    const fmt = horarioSolicitado.setLocale('pt-BR').toFormat('dd/MM (ccc)');
    const hora = horarioSolicitado.toFormat('HH:mm');
    respostaFinal = `✅ O horário solicitado está disponível!\n\n🗓️ *${fmt}* às *${hora}*\n🏥 Unidade: ${configAgenda.nome_unidade}\n👨‍⚕️ Especialista: ${configAgenda.profissional}\n\nDeseja confirmar o agendamento?`;
    sugestoesISO = [horarioSolicitado.toISO()];
} else {
    if (sugestoes.length > 0) {
        const linhas = sugestoes
            .map(s => `🗓️ *${s.setLocale('pt-BR').toFormat('dd/MM (ccc)')}* às *${s.toFormat('HH:mm')}*`)
            .join('\n');

        if (solicitouHorarioEspecifico) {
            respostaFinal = `O horário solicitado não está disponível. Mas encontrei estas opções na unidade ${configAgenda.nome_unidade}:\n\n${linhas}\n\nQual desses fica melhor para você?`;
        } else {
            const txtPeriodo = periodo ? ` para o período da ${periodo}` : '';
            respostaFinal = `Encontrei estes horários disponíveis na unidade ${configAgenda.nome_unidade}${txtPeriodo}:\n\n${linhas}\n\nAlgum desses funciona para você?`;
        }
    } else {
        respostaFinal = `Não encontrei horários disponíveis nos próximos dias na unidade ${configAgenda.nome_unidade}. Gostaria de tentar olhar para a próxima semana?`;
    }
    sugestoesISO = sugestoes.map(s => s.toISO());
}

return {
    json: {
        resultado: respostaFinal,
        sugestoes_iso: sugestoesISO,
        horario_solicitado_disponivel: solicitadoDisponivel
    }
};

const body = $input.first().json.body || $input.first().json;

const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';
const nascimentoPaciente = body.data_nascimento || body.nascimento || '';

const tipoAgenda = (body.tipo_agenda || body.unidade || 'penha').toLowerCase().trim();

const TIMEZONE = 'America/Sao_Paulo';

// REGRAS DE HORÁRIO — Sorria Penha (sem intervalo de almoço registrado no briefing)
// PENHA:   SEG-SEX 08h30-18h00 | SAB 08h30-12h30 | DOM Fechado
// RECREIO: SEG-SEX 09h00-18h00 | SAB 09h00-12h30 | DOM Fechado
// CAXIAS:  SEG-SEX 09h00-18h00 | SAB 09h00-12h30 | DOM Fechado
const REGRAS_PENHA = {
    1: { manha: {ini: {h:8,m:30}, fim: {h:18,m:0}}, tarde: {ini: {h:0,m:0}, fim: {h:0,m:0}} },
    2: { manha: {ini: {h:8,m:30}, fim: {h:18,m:0}}, tarde: {ini: {h:0,m:0}, fim: {h:0,m:0}} },
